"""Shared helpers for compress.py / decompress.py.

Format produced by compress.py inside <output_dir>:

    manifest.json          small JSON describing the archive
    data/                  tree of chunk files, fanout <= MAX_ENTRIES

The payload is a single POSIX tar stream (preserving the full original
directory structure, relative to the input directory), piped through a
streaming compressor, then split into fixed-size chunks.  Chunks are laid out
in a base-N directory tree so that no directory ever holds more than
MAX_ENTRIES entries and no file ever exceeds MAX_FILE_BYTES.
"""

import inspect
import io
import os

MAX_ENTRIES = 30                      # max files+folders per directory
MAX_FILE_BYTES = 14 * 1000 * 1000     # < 15 MB (and < 15 MiB) with headroom

DATA_DIRNAME = "data"
MANIFEST_NAME = "manifest.json"
CHUNK_SUFFIX = ".bin"
FORMAT_VERSION = 1


# --------------------------------------------------------------------------
# chunk tree layout
# --------------------------------------------------------------------------
def _tree_depth(n_chunks, fanout=MAX_ENTRIES):
    """Number of path components (dirs + file) needed under data/."""
    depth = 1
    capacity = fanout
    while capacity < max(n_chunks, 1):
        capacity *= fanout
        depth += 1
    return depth


def chunk_relpath(index, depth, fanout=MAX_ENTRIES):
    """Relative path (POSIX style, below data/) of chunk `index`."""
    digits = []
    value = index
    for _ in range(depth):
        digits.append(value % fanout)
        value //= fanout
    digits.reverse()                      # most significant first
    parts = ["d%02d" % d for d in digits[:-1]]
    parts.append("%06d%s" % (index, CHUNK_SUFFIX))
    return "/".join(parts)


# --------------------------------------------------------------------------
# splitting writer / concatenating reader
# --------------------------------------------------------------------------
class ChunkWriter(io.RawIOBase):
    """File-like sink that splits the byte stream into <= max_bytes chunks.

    Chunks are written under `data_dir`.  Because the number of chunks is not
    known up front, chunks are first written with a provisional flat layout and
    relocated into the final tree by :meth:`finalize`.
    """

    def __init__(self, data_dir, max_bytes=MAX_FILE_BYTES):
        super().__init__()
        self.data_dir = data_dir
        self.max_bytes = max_bytes
        self.staging = os.path.join(data_dir, "__staging__")
        os.makedirs(self.staging, exist_ok=True)
        self._fh = None
        self._written = 0
        self._count = 0
        self.total_bytes = 0

    # io plumbing -------------------------------------------------------
    def writable(self):
        return True

    def _open_next(self):
        if self._fh is not None:
            self._fh.close()
        path = os.path.join(self.staging, "%08d" % self._count)
        self._fh = open(path, "wb")
        self._count += 1
        self._written = 0

    def write(self, b):
        data = memoryview(b).cast("B") if not isinstance(b, (bytes, bytearray)) else b
        view = memoryview(data)
        n = len(view)
        pos = 0
        while pos < n:
            if self._fh is None or self._written >= self.max_bytes:
                self._open_next()
            room = self.max_bytes - self._written
            take = min(room, n - pos)
            self._fh.write(view[pos:pos + take])
            self._written += take
            pos += take
        self.total_bytes += n
        return n

    def close(self):
        if self._fh is not None:
            self._fh.close()
            self._fh = None
        super().close()

    # layout ------------------------------------------------------------
    def finalize(self):
        """Move staged chunks into the fanout-limited tree; return rel paths."""
        self.close()
        depth = _tree_depth(self._count)
        rel_paths = []
        for i in range(self._count):
            rel = chunk_relpath(i, depth)
            dst = os.path.join(self.data_dir, *rel.split("/"))
            os.makedirs(os.path.dirname(dst), exist_ok=True)
            os.replace(os.path.join(self.staging, "%08d" % i), dst)
            rel_paths.append(rel)
        os.rmdir(self.staging)
        return rel_paths


class ChunkReader(io.RawIOBase):
    """File-like source concatenating chunk files back into one stream."""

    def __init__(self, paths):
        super().__init__()
        self.paths = list(paths)
        self._idx = 0
        self._fh = None

    def readable(self):
        return True

    def _advance(self):
        if self._fh is not None:
            self._fh.close()
            self._fh = None
        if self._idx < len(self.paths):
            self._fh = open(self.paths[self._idx], "rb")
            self._idx += 1
            return True
        return False

    def readinto(self, buf):
        while True:
            if self._fh is None and not self._advance():
                return 0
            n = self._fh.readinto(buf)
            if n:
                return n
            if not self._advance():
                return 0

    def read(self, size=-1):
        if size is None or size < 0:
            out = bytearray()
            while True:
                block = self.read(1 << 20)
                if not block:
                    return bytes(out)
                out += block
        buf = bytearray(size)
        n = self.readinto(buf)
        return bytes(buf[:n])

    def close(self):
        if self._fh is not None:
            self._fh.close()
            self._fh = None
        super().close()


# --------------------------------------------------------------------------
# codecs (public APIs only, version-tolerant)
# --------------------------------------------------------------------------
def _zstd_module():
    try:
        import zstandard
        return zstandard
    except Exception:
        return None


def _call_tolerant(func, /, **kwargs):
    """Call `func` passing only kwargs its signature accepts (fall back to all)."""
    try:
        params = inspect.signature(func).parameters
        accepts_var_kw = any(p.kind is inspect.Parameter.VAR_KEYWORD
                             for p in params.values())
        if not accepts_var_kw:
            kwargs = {k: v for k, v in kwargs.items() if k in params}
    except (TypeError, ValueError):
        pass
    while True:
        try:
            return func(**kwargs)
        except TypeError:
            if not kwargs:
                raise
            kwargs.pop(next(reversed(list(kwargs))))


def open_compressor(raw, level=6):
    """Return (stream, codec_name); writing to stream compresses into `raw`."""
    zstd = _zstd_module()
    if zstd is not None:
        cctx = _call_tolerant(zstd.ZstdCompressor, level=level, threads=-1)
        stream = _call_tolerant(cctx.stream_writer, writer=raw)
        return stream, "zstd"
    import gzip
    return gzip.GzipFile(fileobj=raw, mode="wb", compresslevel=6), "gzip"


def open_decompressor(raw, codec):
    if codec == "zstd":
        zstd = _zstd_module()
        if zstd is None:
            raise RuntimeError(
                "archive uses zstd but the 'zstandard' package is unavailable; "
                "run `uv sync` in /app and use `uv run`")
        dctx = zstd.ZstdDecompressor()
        return _call_tolerant(dctx.stream_reader, source=raw)
    if codec == "gzip":
        import gzip
        return gzip.GzipFile(fileobj=raw, mode="rb")
    raise RuntimeError("unknown codec: %r" % (codec,))


# --------------------------------------------------------------------------
# tar helpers
# --------------------------------------------------------------------------
def extractall(tar, path):
    """tarfile.extractall with the strictest-compatible signature."""
    try:
        params = inspect.signature(tar.extractall).parameters
    except (TypeError, ValueError):
        params = {}
    if "filter" in params:
        try:
            return tar.extractall(path=path, filter="fully_trusted")
        except TypeError:
            pass
    return tar.extractall(path=path)

